import json,numpy as np
from PIL import Image
for run in ['/app/output/initial','/app/runs/handle_press_side/02_hover_over_handle','/app/runs/handle_press_side/04_probe_contact']:
 m=json.load(open(run+'/meta.json'))
 print('\n',run)
 for cam in ['front','topview','left']:
  rgb=np.array(Image.open(run+'/last/'+cam+'.jpg')); dep=np.load(run+'/depth_'+cam+'.npy')[0].astype(float); K=np.array(m['cameras'][cam]['intrinsic_cv']); T=np.array(m['cameras'][cam]['cam2world_gl'])
  mask=(rgb[:,:,0]>100)&(rgb[:,:,0]>1.3*rgb[:,:,1])&(rgb[:,:,0]>1.2*rgb[:,:,2])
  if cam=='front': mask &= (np.indices(mask.shape)[0]>85)&(np.indices(mask.shape)[0]<140)&(np.indices(mask.shape)[1]>160)
  if cam=='topview': mask &= (np.indices(mask.shape)[0]>40)&(np.indices(mask.shape)[0]<110)&(np.indices(mask.shape)[1]<155)&(np.indices(mask.shape)[1]>100)
  if cam=='left': mask &= (np.indices(mask.shape)[0]>70)&(np.indices(mask.shape)[0]<145)&(np.indices(mask.shape)[1]<190)
  yy,xx=np.where(mask); arr=[]
  for u,v in zip(xx,yy):
   z=dep[v,u]
   if not (.2<z<10): continue
   gl=np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z,1]); w=(T@gl)[:3]
   if (-.4<w[0]<.1 and .5<w[1]<.9 and .07<w[2]<.25): arr.append(w)
  arr=np.array(arr)
  if len(arr): print(cam,'n',len(arr),'median',np.round(np.median(arr,0),3),'minmax',np.round(arr.min(0),3),np.round(arr.max(0),3))
  else: print(cam,'n 0')
